(function(i){"use strict";i(document).ready(function(){i("textarea#testimonial-content").characterCounter();setTimeout(function(){i(".content:after").css("content","none")},1);i("#submit-testimonial").click(function(t){t.preventDefault();var e=i("#testimonial-content").val().trim().length;if(e<20){i.web2py.flash("Please fill atleast 20 characters")}else if(e<=400){i("#testimonial-form").submit()}else{i.web2py.flash("Character Limit reached")}});i(".love-testimonial").click(function(){var t=i(this),e=i(t.siblings()[0]),s=t.children()[0];if(s.classList.contains("red-text")){i.web2py.flash("Already voted the testimonial")}else{if(loggedIn==="False"){i.web2py.flash("Please login to cast your vote")}else{i.ajax({url:loveTestimonialURL+"/"+i(this).data()["id"],method:"POST",success:function(t){e.html(t["love_count"]);s.classList.add("red-text");i.web2py.flash("Vote submitted")},error:function(t){if(t.status===401){i.web2py.flash("Please login to cast your vote")}else{i.web2py.flash("Error submitting your vote")}}})}}})})})(jQuery);